<?= $this->extend('layout') ?><?= $this->section('content') ?><style>.dv-table td[style*="display:flex"]{display:table-cell!important;text-align:center!important;vertical-align:middle}.dv-table td[style*="display:flex"] form{display:inline-block;vertical-align:middle;margin:0 2px}.dv-table td[style*="display:flex"] .act{display:inline-flex;align-items:center;justify-content:center}.role,.status{display:inline-block;padding:3px 9px;border-radius:999px;font-size:.7rem;font-weight:700}.role-super-admin{background:#eee6ff;color:#7147dc}.role-analyste{background:#ffe7f1;color:#d72669}.role-saisie{background:#e3efff;color:#2778e8}.role-visiteur{background:#fff4d7;color:#a86b00}.role-visualiseur{background:#e2f9f2;color:#07875c}.status-actif{background:#dff9e8;color:#159447}.status-inactif{background:#ffe5e8;color:#d8334a}.dv-table th:last-child,.dv-table td:last-child{text-align:right;padding-right:26px}.dv-table td:last-child>div{justify-content:flex-end}.dv-table th:last-child,.dv-table td:last-child{text-align:right;min-width:150px}.dv-table td:last-child>div{justify-content:flex-end}.act{border:0!important}.dv-stat:nth-child(1){border-left:3px solid #1677ff}.dv-stat:nth-child(2){border-left:3px solid #16a05d}.dv-stat:nth-child(3){border-left:3px solid #e55353}.dv-badge{font-weight:700}.modal{display:none;position:fixed;inset:0;z-index:999;background:#0009;backdrop-filter:blur(7px);align-items:center;justify-content:center}.modal.open{display:flex}.modal .dv-card{width:min(600px,92vw)}.act{padding:7px 10px}</style><h1>Gestion des utilisateurs</h1><div class="dv-stats-grid"><?php foreach(['Total'=>'total','Actifs'=>'actifs','Inactifs'=>'inactifs'] as $l=>$k):?><div class="dv-stat"><div class="dv-stat-label"><?= $l ?></div><div class="dv-stat-value"><?= $stats[$k] ?></div></div><?php endforeach?></div><form method="get" class="dv-card" style="display:flex;gap:8px"><input class="dv-input" name="q" value="<?= esc(service('request')->getGet('q')) ?>" placeholder="Rechercher nom, email…"><select class="dv-select" name="role"><option value="">Tous les rôles</option><?php foreach(['Super Admin','Saisie','Visiteur','Visualiseur','Analyste'] as $r):?><option value="<?= $r ?>" <?= service('request')->getGet('role')===$r?'selected':'' ?>><?= $r ?></option><?php endforeach?></select><button class="dv-btn dv-btn-primary"><i class="bi bi-funnel"></i> Filtrer</button><button type="button" class="dv-btn dv-btn-success" onclick="m(1)"><i class="bi bi-plus"></i> Nouveau</button></form><div class="dv-card"><table class="dv-table"><thead><tr><th>Utilisateur</th><th>Rôle</th><th>Statut</th><th>Dernière connexion</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?= esc(trim($u['prenom'].' '.$u['nom'])?:$u['username']) ?></b><br><small><?= esc($u['email']) ?></small></td><td><span class="role role-<?= strtolower(str_replace(" ", "-", $u["role"])) ?>"><?= esc($u["role"]) ?></span></td><td><span class="status status-<?= strtolower($u["statut"]) ?>"><?= esc($u["statut"]) ?></span></td><td><?= esc($u['derniere_connexion']?:'—') ?></td><td style="display:flex;gap:5px"><button class="dv-btn dv-btn-outline act" onclick='e(<?= json_encode($u) ?>)'><i class="bi bi-pencil"></i></button><form method="post" action="<?= site_url('utilisateurs/'.$u['user_id'].'/statut') ?>"><?= csrf_field() ?><button class="dv-btn dv-btn-success act" title="Autoriser/Bloquer"><i class="bi <?= $u['statut']==='Actif'?'bi-toggle-on':'bi-toggle-off' ?>"></i></button></form><form method="post" action="<?= site_url('utilisateurs/'.$u['user_id'].'/supprimer') ?>" onsubmit="return confirm('Supprimer ?')"><?= csrf_field() ?><button class="dv-btn act" style="background:#e55353"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach?></tbody></table></div><div id="modal" class="modal"><form class="dv-card" method="post" action="<?= site_url('utilisateurs') ?>"><?= csrf_field() ?><h3>Nouvel utilisateur</h3><input class="dv-input" name="username" placeholder="Identifiant" required><br><input class="dv-input" name="email" placeholder="Email" type="email" required><br><input class="dv-input" name="prenom" placeholder="Prénom"><br><input class="dv-input" name="nom" placeholder="Nom"><br><select class="dv-select" name="role"><option>Super Admin</option><option>Saisie</option><option>Visiteur</option><option>Visualiseur</option><option>Analyste</option></select><br><input class="dv-input" name="password" type="password" placeholder="Mot de passe" required><p><button class="dv-btn dv-btn-primary">Créer</button><button type="button" class="dv-btn dv-btn-outline" onclick="m(0)">Annuler</button></p></form></div><div id="editModal" class="modal"><form class="dv-card" method="post" id="editForm"><?= csrf_field() ?><h3>Modifier l'utilisateur</h3><input class="dv-input" id="editPrenom" name="prenom" placeholder="Prénom"><br><input class="dv-input" id="editNom" name="nom" placeholder="Nom"><br><input class="dv-input" id="editEmail" name="email" type="email" required><br><select class="dv-select" id="editRole" name="role"><option>Super Admin</option><option>Saisie</option><option>Visiteur</option><option>Visualiseur</option><option>Analyste</option></select><p><button class="dv-btn dv-btn-primary">Enregistrer</button><button type="button" class="dv-btn dv-btn-outline" onclick="editModal.classList.remove('open')">Annuler</button></p></form></div><script>function m(x){modal.classList.toggle('open',!!x)}function e(u){editPrenom.value=u.prenom||'';editNom.value=u.nom||'';editEmail.value=u.email||'';editRole.value=u.role;editForm.action='<?= site_url('utilisateurs') ?>/'+u.user_id;editModal.classList.add('open')}</script><?= $this->endSection() ?>
